<template><view class="page"><view v-for="item in list" :key="item.id" class="card"><view class="row"><text>{{item.applyNo}}</text><text class="status">{{item.statusText||item.status}}</text></view><text>当前上级：{{item.currentParentName||'平台渠道'}}</text><text>目标上级：{{item.targetParentName||'目标上级名称待补充'}}</text><text>原因：{{item.applyReason}}</text><text v-if="item.rejectReason" class="warn">驳回原因：{{item.rejectReason}}</text><button v-if="item.status==='PENDING'" size="mini" @click="cancel(item)">取消申请</button></view><view v-if="!list.length" class="empty">暂无换绑记录</view></view></template>
<script>import{getJkRelationChangeList,cancelJkRelationChange}from'@/api/jk.js';export default{data(){return{list:[]}},onShow(){this.load()},methods:{load(){getJkRelationChangeList({page:1,limit:50}).then(r=>{const p=r.data||r||{};this.list=p.list||[]})},cancel(item){uni.showModal({title:'取消换绑申请',editable:true,placeholderText:'请输入取消原因',success:r=>{if(r.confirm)cancelJkRelationChange(item.id,{requestNo:'REL-CANCEL-'+Date.now(),reason:r.content||'用户主动取消'}).then(()=>this.load())}})}}}</script>
<style scoped>.page{min-height:100vh;background:#f3f8f6;padding:24rpx}.card{display:flex;flex-direction:column;gap:12rpx;margin-bottom:18rpx;padding:26rpx;border-radius:20rpx;background:#fff;color:#567168}.row{display:flex;justify-content:space-between;color:#28594a;font-weight:600}.status{color:#1a9f75}.warn{color:#bd6817}.empty{text-align:center;color:#9aaea6;padding:120rpx}</style>
